struct sk_buff *reassemble_ipv6_fragments(struct nf_ct_frag6_queue *fq, struct net_device *dev)
{
    struct sk_buff *skb;
    int payload_len;

    if (!fq || !dev)
        return NULL;

    payload_len = fq->payload_len;
    if (payload_len <= 0)
        return NULL;

    skb = alloc_skb(payload_len, GFP_ATOMIC);
    if (!skb)
        return NULL;

    if (fq->first->flags & IPV6_FLOWLbl_MASK) {
        net_dbg_ratelimited("First fragment itself is fragmented.\n");
        kfree_skb(skb);
        return NULL;
    }

    if (skb_copy_and_build_header(skb, fq->first, dev)) {
        net_dbg_ratelimited("Failed to copy header.\n");
        kfree_skb(skb);
        return NULL;
    }

    if (skb_remake_header(skb)) {
        net_dbg_ratelimited("Failed to adjust headers.\n");
        kfree_skb(skb);
        return NULL;
    }

    if (skb_linearize(skb)) {
        net_dbg_ratelimited("Failed to linearize SKB.\n");
        kfree_skb(skb);
        return NULL;
    }

    if (nf_ct_frag6_reassemble(skb, fq)) {
        net_dbg_ratelimited("Reassembly failed.\n");
        kfree_skb(skb);
        return NULL;
    }

    skb->ip_summed = CHECKSUM_UNNECESSARY;
    skb->pkt_type = PACKET_HOST;
    skb->dev = dev;
    skb->protocol = htons(ETH_P_IPV6);

    return skb;
}

struct sk_buff *reassemble_ipv6_fragments(struct nf_ct_frag6_queue *fq, struct net_device *dev) {
