{
    struct sk_buff *skb;
    int payload_len;

    if (!fq || !dev)
        return NULL;

    payload_len = fq->me->len;
    if (!payload_len)
        return NULL;

    skb = alloc_skb(payload_len, GFP_ATOMIC);
    if (!skb)
        return NULL;

    if (fq->flags & NF_CT_FRAG6_FIRST_FRAG && fq->first->prev) {
        /* First fragment itself is fragmented */
        skb_free(skb);
        return NULL;
    }

    skb->protocol = htons(ETH_P_IPV6);

    skb->dev = dev;
    skb->pkt_type = PACKET_HOST;
    skb->ip_summed = CHECKSUM_NONE;

    skb->len = payload_len;

    if (skb_copy_and_csum_dev(fq->skb, skb) != 0) {
        skb_free(skb);
        return NULL;
    }

    return skb;
}

struct sk_buff *reassemble_ipv6_fragments(struct nf_ct_frag6_queue *fq, struct net_device *dev) {
    struct sk_buff *skb;
    int payload_len;

    if (!fq || !dev)
        return NULL;

    payload_len = fq->payload_len;
    if (payload_len <= 0)
        return NULL;

    skb = alloc_skb(payload_len + sizeof(struct ipv6hdr), GFP_ATOMIC);
    if (!skb) {
        pr_debug("Failed to allocate memory for reassembled IPv6 packet\n");
        return NULL;
    }

    if (fq->first && (fq->first->flags & IP6_F_OFF_MASK)) {
        pr_debug("First fragment is itself fragmented; cannot reassemble\n");
        kfree_skb(skb);
        return NULL;
    }

    skb_reserve(skb, sizeof(struct ipv6hdr));
    skb_reset_network_header(skb);
    skb->dev = dev;

    while (fq->fragments) {
        struct sk_buff *fragment = fq->fragments;
        int offset = ntohs(fq->fragments->h->frag_off) & IP6_F_OFF_MASK;

        if (offset >= payload_len) {
            kfree_skb(skb);
            pr_debug("Invalid fragment offset during reassembly\n");
            return NULL;
        }

        skb_copy_from_linear_data(fq->fragments, skb->data + offset, skb_tailroom(skb));
        fq->fragments = fq->fragments->next;
    }

    skb_put(skb, payload_len);
    skb->len = payload_len + sizeof(struct ipv6hdr);
    skb->data_len = payload_len;
    skb->truesize += payload_len;

    return skb;
}

struct sk_buff *reassemble_ipv6_fragments(struct nf_ct_frag6_queue *fq, struct net_device *dev) {
    struct sk_buff *skb;
    int payload_len, hlen;
    int err;

    if (!fq || !dev)
        return NULL;

    payload_len = nf_ct_frag6_queue_payload_len(fq);
    if (payload_len <= 0)
        return NULL;

    skb = alloc_skb(payload_len, GFP_ATOMIC);
    if (!skb)
        return NULL;

    hlen = sizeof(struct ipv6hdr);

    if (fq->frag_first) {
        if (fq->frag_first->offset || (fq->frag_first->nhoff != hlen)) {
            NETDEV_ERR(dev, "Invalid first fragment\n");
            kfree_skb(skb);
            return NULL;
        }

        skb_set_network_header(skb, 0);
        skb_copy_from_linear_data(fq->frag_first->skb, skb->data, hlen);
        skb_reserve(skb, hlen);
    }

    for (int i = 0; i < fq->nr_frags; i++) {
        struct nf_ct_frag6_skb_cb *f = &NF_CT_FRAG6_SKB_CB(fq->frags[i].skb);

        if (f->offset != fq->offset[i]) {
            NETDEV_ERR(dev, "Fragment offset mismatch\n");
            kfree_skb(skb);
            return NULL;
        }

        if (f->offset + f->size > payload_len) {
            NETDEV_ERR(dev, "Fragment overflow\n");
            kfree_skb(skb);
            return NULL;
        }

        skb_add_data(skb, f->offset, f->size, fq->frags[i].skb);
    }

    if (skb->len != payload_len) {
        NETDEV_ERR(dev, "Reassembly length mismatch\n");
        kfree_skb(skb);
        return NULL;
    }

    err = ip6_hdr(skb)->payload_len = htons(skb->len - hlen);
    skb->ip_summed = CHECKSUM_UNNECESSARY;

    return skb;
}
